pub fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> (Vec<f32>) {
    assert_eq!(a.len(), mask.len(), "mask length must match input length");
    assert!(!values.is_empty(), "values must be non-empty");

    let vlen = values.len();
    let mut result = Vec::with_capacity(a.len());

    for (i, (ai, mi)) in a.into_iter().zip(mask.into_iter()).enumerate() {
        if mi {
            result.push(values[i % vlen]);
        } else {
            result.push(ai);
        }
    }

    result
}